   app.get('/users/:id', async (req, res, next) => {
     try {
       const { id } = req.params;
       const result = await pool.query('SELECT id, name, email FROM users WHERE id = $1', [id]);
       if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
       res.json(result.rows[0]);
